import{_ as e,o as r,c as o,a3 as n}from"./chunks/framework.Cj_fzHAr.js";const s="/manual/img/guia-inicio/login.png",g=JSON.parse('{"title":"Cómo ingresar a la plataforma","description":"","frontmatter":{},"headers":[],"relativePath":"guia-inicio/instalacion.md","filePath":"guia-inicio/instalacion.md"}'),t={name:"guia-inicio/instalacion.md"};function i(l,a,c,u,d,m){return r(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="como-ingresar-a-la-plataforma" tabindex="-1">Cómo ingresar a la plataforma <a class="header-anchor" href="#como-ingresar-a-la-plataforma" aria-label="Permalink to &quot;Cómo ingresar a la plataforma&quot;">​</a></h1><p>Build &amp; Serve funciona desde el <strong>navegador</strong> (Chrome, Edge, Safari, etc.), tanto en computador como en el teléfono. No necesitas instalar ninguna aplicación: basta con abrir la dirección web que te entregue tu empresa e iniciar sesión.</p><h2 id="iniciar-sesion" tabindex="-1">Iniciar sesión <a class="header-anchor" href="#iniciar-sesion" aria-label="Permalink to &quot;Iniciar sesión&quot;">​</a></h2><ol><li>Abre el <strong>enlace de la plataforma</strong> que te compartió tu empresa.</li><li>En la pantalla <strong>&quot;Iniciar sesión&quot;</strong>, ingresa: <ul><li><strong>RUT</strong> — tu RUT (por ejemplo <em>12.345.678-9</em>).</li><li><strong>Contraseña</strong> — la contraseña de tu cuenta.</li></ul></li><li>Haz clic en <strong>Ingresar</strong>.</li></ol><p><img src="'+s+'" alt="Pantalla de inicio de sesión con los campos RUT y Contraseña"></p><blockquote><p>👁️ Puedes usar el ícono del ojo en el campo de contraseña para <strong>mostrar u ocultar</strong> lo que escribes y asegurarte de no equivocarte.</p></blockquote><h2 id="primer-ingreso" tabindex="-1">Primer ingreso <a class="header-anchor" href="#primer-ingreso" aria-label="Permalink to &quot;Primer ingreso&quot;">​</a></h2><p>Si es la primera vez que entras, lo más probable es que tu empresa te haya entregado una <strong>contraseña temporal</strong>. Al ingresar con ella, el sistema te pedirá <strong>crear tu propia contraseña</strong>. Elige una que recuerdes y no compartas con nadie.</p><p>Durante la configuración de tu cuenta también definirás tu <strong>PIN de 4 dígitos</strong>, que es el que usarás para <strong>firmar documentos</strong> (es distinto de tu contraseña). Consulta el módulo de <a href="/manual/modulos/firmas.html">Firmas Digitales</a>.</p><h2 id="olvide-mi-contrasena" tabindex="-1">Olvidé mi contraseña <a class="header-anchor" href="#olvide-mi-contrasena" aria-label="Permalink to &quot;Olvidé mi contraseña&quot;">​</a></h2><p>Si no recuerdas tu contraseña:</p><ol><li>En la pantalla de inicio de sesión, haz clic en <strong>&quot;¿Olvidaste tu contraseña?&quot;</strong>.</li><li>Sigue las instrucciones para restablecerla.</li></ol><p>Si el problema persiste, contacta al <strong>administrador de tu empresa</strong>, que puede ayudarte a restablecer tu acceso.</p><h2 id="recomendaciones-de-acceso" tabindex="-1">Recomendaciones de acceso <a class="header-anchor" href="#recomendaciones-de-acceso" aria-label="Permalink to &quot;Recomendaciones de acceso&quot;">​</a></h2><ul><li>Usa un navegador actualizado para una mejor experiencia.</li><li>Desde el teléfono funciona igual: ideal para firmar y registrar asistencia <strong>en terreno</strong>.</li><li>Si trabajas en una obra <strong>sin señal</strong>, revisa las <a href="/manual/modulos/firmas.html">Firmas Offline</a>: te permiten operar sin conexión y sincronizar después.</li><li>Cierra sesión si usas un equipo compartido.</li></ul><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Necesito instalar algo?</strong> No. La plataforma funciona en el navegador. Solo necesitas el enlace y tu RUT y contraseña.</p><p><strong>¿Puedo entrar desde el celular?</strong> Sí. Está pensada para usarse también desde el teléfono, especialmente para firmar y registrar actividades en obra.</p><p><strong>Ingreso mi RUT y contraseña pero no entra.</strong> Revisa que el RUT esté bien escrito (con guion y dígito verificador) y que la contraseña sea la correcta. Si tienes una contraseña temporal, puede haber caducado: usa &quot;¿Olvidaste tu contraseña?&quot; o pide ayuda al administrador.</p><p><strong>¿La contraseña y el PIN son lo mismo?</strong> No. La <strong>contraseña</strong> sirve para iniciar sesión; el <strong>PIN</strong> (4 dígitos) sirve para <strong>firmar</strong> documentos dentro de la plataforma. Son independientes.</p><p><strong>No tengo cuenta. ¿Cómo consigo una?</strong> Las cuentas las crea el administrador de tu empresa en el módulo de <a href="/manual/modulos/personas.html">Personas</a>. Pídele que te registre y te entregue tu acceso.</p>',21)])])}const f=e(t,[["render",i]]);export{g as __pageData,f as default};
